import{z as s,x as i,o as r,c as B,q as p,j as o,D as E,d as e,s as A,S as n,b as t}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"EMA 与检查点平均","description":"","frontmatter":{"title":"EMA 与检查点平均","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ema-checkpoint-averaging.md","filePath":"llm/ema-checkpoint-averaging.md","lastUpdated":1791063341000}'),d={name:"llm/ema-checkpoint-averaging.md"};function m(h,a,u,D,g,b){const l=i("Mermaid");return r(),B("div",null,[a[2]||(a[2]=p('<h1 id="ema-与检查点平均" tabindex="-1">EMA 与检查点平均 <a class="header-anchor" href="#ema-与检查点平均" aria-label="Permalink to &quot;EMA 与检查点平均&quot;">​</a></h1><div class="epigraph"><p>对权重做时间上的滑动平均，得到的是更宽盆地里的一点；训练损失未必最低，测试往往更稳。</p><footer>—— Polyak &amp; Juditsky, SIAM J. Control Optim., 1992；SWA 见 Izmailov et al., Averaging Weights Leads to Wider Optima, UAI 2018</footer></div><p><a href="/llm/weight-decay-exemptions">上一课</a>把单步更新的参数分组钉住。缺口是时间轴：同一条轨迹上，后期权重在尖峰两侧抖动，任意一个 step 的检查点可能落在尖刺上。Polyak 平均与 Izmailov 等人的 SWA 把一段轨迹上的 \\(\\theta_t\\) 平均成 \\(\\bar\\theta\\)。EMA 是在线版：每步 \\(\\bar\\theta\\leftarrow \\tau\\bar\\theta+(1-\\tau)\\theta\\)。本课写训练期如何维护这条影子权重，下一课的模型汤才把<strong>不同超参跑出来的模型</strong>再平均。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>余弦尾或 WSD 的稳定段里，\\(\\eta\\) 仍非零，权重在盆地里走。验证 CE 的最佳点往往不是训练 CE 的最佳点，也不是最后一个 step。若只存最后一步，可能正好存到一次 \\(\\beta_2\\) 尖峰之后。平均把高频抖动滤掉，等价于在参数空间做低通。Izmailov 等人说明：平均解的 Hessian 更小（更宽），泛化更好。对 LLM，下游比训练 CE 更关心，EMA 检查点常作为对外权重。</p><p>代价：\\(\\bar\\theta\\) 不在训练图上，不能用 \\(\\bar\\theta\\) 的梯度去继续 Adam。EMA 是旁路。把训练切到 \\(\\bar\\theta\\) 再继续，等于换了一套不再匹配 \\(m,v\\) 的权重，需要重置优化器状态，本课默认不这么做。</p><p><span class="marginnote">可以把 EMA 想成音频里的低通滤波器：权重在盆地内的高频抖动是背景噪声，\\(\\tau\\) 越大滤得越干净、但对新变化的反应也越慢；一次 loss 尖峰好比突发的爆音，不会被立刻删掉，而是被平均拖成一条缓慢衰减的长尾。</span></p><p><span class="marginnote">\\(\\tau\\) 接近 1（如 0.999）时，EMA 半衰期很长，早期压熵段的权重会污染很久。应在 warmup 结束或进入幂律段之后再启动 EMA，或使用偏差修正。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>EMA。</strong> 选择 \\(\\tau\\)（或等价的 decay）。每步在 <code>no_grad</code> 下更新影子。评测与对外保存用 \\(\\bar\\theta\\)，训练继续用 \\(\\theta\\)。BF16 训练时影子建议 FP32，避免平均被舍入抵消。</p><p><strong>SWA / 检查点算术平均。</strong> 在日程尾部每隔 \\(k\\) 步存一个 \\(\\theta\\)，最后均匀平均。不需要每步维护影子，但要磁盘。与 EMA 相比，SWA 明确「从哪一步开始进入平均窗口」，对余弦尾更好解释。</p><p><span class="marginnote">算一笔磁盘账：一个 7B 参数模型的 FP32 检查点约 \\(7\\times10^9\\times4\\) 字节 \\(\\approx 28\\) GB。SWA 尾部每 1000 步存一个、存 20 个就是约 560 GB；EMA 只需常驻一份同样大小的影子，开销不随窗口长度增长。</span></p><p><strong>Polyak 意义下的全程平均</strong>对 LLM 通常太重：早期权重与后期不在同一盆地。窗口应限制在损失曲线阶段课里的幂律后段与衰减段。</p><p>不要把 EMA 当学习率衰减的替代：它不缩小更新，只平滑参数。\\(\\eta\\) 仍按日程走。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>若 \\(\\theta_t=\\theta^*+\\xi_t\\)，\\(\\xi\\) 近零均值高频噪声，平均把 \\(\\xi\\) 压低。若尖峰把 \\(\\theta\\) 打到远处，EMA 会拖一条长尾巴——\\(\\tau\\) 很大时，一次尖峰污染半个半衰期。对策是：尖峰后从最近的干净检查点恢复 \\(\\theta\\)，并<strong>重置</strong> EMA 为该检查点，或暂时降低 \\(\\tau\\)。只恢复 \\(\\theta\\) 不重置 \\(\\bar\\theta\\)，影子仍含尖刺。</p><p><span class="marginnote">初学者容易以为把 \\(\\theta\\) 恢复到干净检查点就万事大吉；实际上 \\(\\bar\\theta\\) 是全部历史的加权和，尖峰的份量早已按 \\((1-\\tau)\\) 记进影子。不重置影子，污染会按半衰期慢慢渗回之后的每一次评测。</span></p>',17)),(r(),o(n,null,{default:E(()=>[A(l,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E8%AE%AD%E7%BB%83%E4%B8%AD%E5%8F%91%E7%94%9F%20loss%20%E5%B0%96%E5%B3%B0%22%5D%20--%3E%20THETA%5B%22theta%20%E8%A2%AB%E6%89%93%E5%88%B0%E8%BF%9C%E5%A4%84%22%5D%0A%20%20THETA%20--%3E%20REC%5B%22%E4%BB%8E%E6%9C%80%E8%BF%91%E5%B9%B2%E5%87%80%E6%A3%80%E6%9F%A5%E7%82%B9%E6%81%A2%E5%A4%8D%20theta%22%5D%0A%20%20REC%20--%3E%20Q%7B%22%E8%A6%81%E4%B8%8D%E8%A6%81%E9%87%8D%E7%BD%AE%E5%BD%B1%E5%AD%90%3F%22%7D%0A%20%20Q%20--%20%22%E9%87%8D%E7%BD%AE%20bar%20theta%20%E4%B8%BA%E8%AF%A5%E6%A3%80%E6%9F%A5%E7%82%B9%22%20--%3E%20CLEAN%5B%22%E5%BD%B1%E5%AD%90%E5%B9%B2%E5%87%80%2C%20%E8%AF%84%E6%B5%8B%E5%8F%AF%E4%BF%A1%22%5D%0A%20%20Q%20--%20%22%E5%8F%AA%E6%81%A2%E5%A4%8D%20theta%22%20--%3E%20DIRTY%5B%22%E5%BD%B1%E5%AD%90%E4%BB%8D%E5%90%AB%E5%B0%96%E5%88%BA%E4%BB%BD%E9%87%8F%22%5D%0A%20%20DIRTY%20--%3E%20TAIL%5B%22%E6%8C%89%E5%8D%8A%E8%A1%B0%E6%9C%9F%E6%8B%96%E5%AE%BD%E6%95%B0%E7%99%BE%E6%AD%A5%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,"与 dropout：训练 \\(\\theta\\) 在噪声下更新，\\(\\bar\\theta\\) 近似期望网络，和 inverted dropout 的推理动机同类，但作用在参数而不是激活。已关 dropout 的大模型预训练上，EMA 的收益主要来自滤尖峰与宽盆地，而不是滤 dropout 噪声。",-1)),a[4]||(a[4]=t("h2",{id:"边界",tabindex:"-1"},[e("边界 "),t("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[5]||(a[5]=t("p",null,[e("本课平均的是"),t("strong",null,"同一条轨迹"),e("。不同种子、不同 \\(\\eta\\)、不同微调任务的平均是模型汤与任务向量，后两课。LoRA 只平均适配器时，基座必须相同。量化应在 \\(\\bar\\theta\\) 上做，不要先量化再平均（非线性）。")],-1)),a[6]||(a[6]=t("p",null,"分布式下每个 rank 维护本地影子再同步，必须与参数分片对齐，否则平均的是残缺向量。下一课把多条轨迹请进同一盆地方向的假设里。",-1)),(r(),o(n,null,{default:E(()=>[A(l,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20TH%5B%22%E8%AE%AD%E7%BB%83%E6%9D%83%E9%87%8D%20theta%22%5D%20--%3E%20OPT%5B%22AdamW%20%E6%9B%B4%E6%96%B0%22%5D%0A%20%20TH%20--%3E%20EMA%5B%22%E5%BD%B1%E5%AD%90%20bar%20theta%22%5D%0A%20%20OPT%20--%3E%20TH%0A%20%20EMA%20--%3E%20SAVE%5B%22%E8%AF%84%E6%B5%8B%E4%B8%8E%E5%AF%B9%E5%A4%96%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=t("h2",{id:"小结",tabindex:"-1"},[e("小结 "),t("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[8]||(a[8]=t("ul",null,[t("li",null,"EMA / SWA 滤的是同一轨迹上的高频抖动，得到更宽盆地里的点。"),t("li",null,"影子不进 Adam；尖峰恢复时要同时重置 EMA。"),t("li",null,"平均窗口避开压熵段；影子用 FP32。"),t("li",null,"不是学习率衰减，也不是跨模型汤。"),t("li",null,"出处：Polyak & Juditsky, 1992；Izmailov et al., UAI 2018。")],-1))])}const c=s(d,[["render",m]]);export{f as __pageData,c as default};
